#!/bin/bash

check_date() {
    input="$1"
    expected="$2"
    result=$(echo "$input" | ./date_norm)
    
    if [ "$result" = "$expected" ]; then
        echo "✅ Test passed for input: '$input'"
    else
        echo "❌ Test failed for input: '$input'"
        echo "   Expected: '$expected'"
        echo "   Actual:   '$result'"
    fi
}

